def count_odd_sum_pairs(nums):
    """
    Returns the count of distinct pairs (i, j) where i < j and nums[i] + nums[j] is an odd number.
    """
    count = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if (nums[i] + nums[j]) % 2 != 0:
                count += 1
    return count
